#!/bin/bash
# Final receipts: fresh git clone of each published repo at its pinned commit.
MODE=$1; OUT=$2; W=$HOME/receipt_$(date -u +%Y%m%d_%H%M); rm -rf $W; mkdir -p $W; cd $W
if [ "$MODE" = john ]; then export PATH="$HOME/.local/gitonly:$HOME/.elan/bin:/usr/bin:/bin:/usr/sbin:/sbin:$HOME/.local/bin"; PK=$HOME/lean/clifford/.lake/packages; SHA="shasum -a 256"; ulimit -n 10240; bash $HOME/lean/fix-mathlib.sh >/dev/null 2>&1; else export PATH=$HOME/.elan/bin:$PATH; PK=$HOME/barbier/.lake/packages; SHA=sha256sum; fi
echo "RECEIPT $MODE $(date -u) host=$(hostname) arch=$(uname -m)" > $OUT; echo "lean: $(lean --version)" >> $OUT
echo "===== clifford pin 209abaa5e638f37aee8ec374e29b74341297cc46" >> $OUT; git clone -q https://github.com/jpbald93/clifford clifford && cd clifford && git checkout -q 209abaa5e638f37aee8ec374e29b74341297cc46 && echo "HEAD $(git rev-parse HEAD) status:$(git status --porcelain | wc -l | tr -d " ")" >> $OUT && echo "mathlib $(grep -A6 '"name": "mathlib"' lake-manifest.json | grep '"rev"' | tr -d ' ",')" >> $OUT && find . -name "*.lean" -not -path "./.git/*" -not -path "./.lake/*" -not -path "./tests/*" | LC_ALL=C sort | xargs $SHA >> $OUT && mkdir -p .lake && ln -s $PK .lake/packages && lake build > build.log 2>&1; echo "build rc=$?" >> $OUT; bash gate.sh 2>&1 | tail -1 >> $OUT; bash tests/tamper.sh 2>&1 | tail -1 >> $OUT; cd $W
